// Deterministic delivery model. No randomness, no clock.
// One message, one worker that crashes exactly once on its FIRST delivery,
// at the configured point. The broker redelivers any message it never saw
// acked; the redelivery (attempt 2) runs clean. We count real card charges.
const MSG_ID = 'msg-7a3f';
function run(ackBeforeProcess) {
  const dedup = {};            // dedup record + charge commit together (atomic)
  const useDedup = !ackBeforeProcess && true === arguments[1];
  let charges = 0;             // real side effects on the card
  let acked = false;
  for (let attempt = 1; attempt <= 5 && !acked; attempt++) {
    if (ackBeforeProcess) {
      acked = true;            // ACK-BEFORE-PROCESS: broker drops the msg now
      if (attempt === 1) continue;   // crash before the charge -> nothing happens
    }
    if (useDedup && dedup[MSG_ID]) { acked = true; continue; } // skip duplicate
    charges++;                 // charge the card
    if (useDedup) dedup[MSG_ID] = true;
    if (!ackBeforeProcess && attempt === 1) continue; // crash after charge, pre-ack
    acked = true;             // ACK-AFTER-PROCESS: safe to ack now
  }
  return charges;
}
const atMostOnce  = run(true);          // ack-before-process: charge LOST -> 0
const atLeastOnce = run(false, false);  // ack-after, no dedup: DUPLICATE -> 2
const exactlyOnce = run(false, true);   // ack-after + dedup: FIXED -> 1
console.log('at-most-once charges: ' + atMostOnce);
console.log('at-least-once charges: ' + atLeastOnce);
console.log('exactly-once-processing charges: ' + exactlyOnce);
console.log('verdict: lost=' + (atMostOnce === 0) + ' duplicate=' + (atLeastOnce === 2) + ' fixed=' + (exactlyOnce === 1));
